class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = Object.assign({
      cur: 'support', view: 'list', q: '', helpOpen: false, draft: '', pend: [], zoom: null, ferr: '', err: false, toast: '',
      read: {},
      thr: {
        support: [{ me: false, t: 'Привет! Я AI-ассистент поддержки. Задайте вопрос - я помогу или переведу на специалиста.', time: '09:00', day: 'Сегодня' }],
        kamila: [{ me: false, t: 'Здравствуйте! Клиент Дмитрий Орлов на связи, ждёт материалы.', time: '10:58', day: 'Сегодня' }, { me: false, t: 'Да, пришлю план этажа сегодня', time: '11:12', day: 'Сегодня' }, { me: false, t: '**Материалы по сделке** готовы:\n- план этажа (PDF)\n- договор на подпись\n- [презентация объекта](https://housebook.ae)\n\nКаталог: https://housebook.ae/catalog', time: '11:20', day: 'Сегодня' }],
        georgiy: [{ me: false, t: 'Показ дома назначен на 12 ноября', time: '18:30', day: 'Вчера' }],
        aliya: [{ me: false, t: 'Договор отправлен клиенту на почту', time: '14:20', day: '3 ноября' }]
      }
    }, {});
  }
  componentDidMount() {
    this.syncMsg(); this.toEnd();
    this._dnd = (e) => {
      const dt = e.dataTransfer; if (!dt || !Array.from(dt.types || []).includes('Files')) return;
      e.preventDefault();
      const r = document.querySelector('.mlayout__r'), inR = !!r && r.contains(e.target) && getComputedStyle(r).display !== 'none';
      if (e.type === 'drop') { clearTimeout(this._dt); if (r) r.classList.remove('is-drop'); if (inR) this.addFiles(dt.files); return; }
      if (inR) { r.classList.add('is-drop'); clearTimeout(this._dt); this._dt = setTimeout(() => r.classList.remove('is-drop'), 150); }
    };
    ['dragenter', 'dragover', 'drop'].forEach((n) => document.addEventListener(n, this._dnd));
  }
  componentDidUpdate() { this.syncMsg(); this.toEnd(); }

  mdRender() {
    const ok = (u) => { try { return /^(https?:|mailto:)$/.test(new URL(u).protocol); } catch (e) { return false; } };
    const el = (tag, par, cls) => { const e = document.createElement(tag); if (cls) e.className = cls; par.appendChild(e); return e; };
    const link = (par, txt, u) => { if (!ok(u)) { par.appendChild(document.createTextNode(txt)); return; } const a = el('a', par); a.href = u; a.target = '_blank'; a.rel = 'noopener noreferrer'; a.textContent = txt; };
    const RE = /`([^`\n]+)`|\[([^\]\n]+)\]\(((?:[^\s()]|\([^\s()]*\))+)\)|(https?:\/\/[^\s<]*[^\s<.,;:!?)])|\*\*(.+?)\*\*|~~(.+?)~~|\*([^*\n]+?)\*|(?<![\p{L}\p{N}])_([^_\n]+?)_(?![\p{L}\p{N}])/gsu;
    const inl = (par, s) => {
      let i = 0, m; const re = new RegExp(RE.source, 'gsu');
      while ((m = re.exec(s))) {
        if (m.index > i) par.appendChild(document.createTextNode(s.slice(i, m.index)));
        if (m[1] !== undefined) el('code', par).textContent = m[1];
        else if (m[2] !== undefined) link(par, m[2], m[3]);
        else if (m[4] !== undefined) link(par, m[4], m[4]);
        else if (m[5] !== undefined) inl(el('strong', par), m[5]);
        else if (m[6] !== undefined) inl(el('s', par), m[6]);
        else inl(el('em', par), m[7] !== undefined ? m[7] : m[8]);
        i = re.lastIndex;
      }
      if (i < s.length) par.appendChild(document.createTextNode(s.slice(i)));
    };
    document.querySelectorAll('.bub .md').forEach((root) => {
      const src = root.getAttribute('data-src') || '';
      if (root.__src === src && root.firstChild) return;
      root.__src = src; root.textContent = '';
      const ls = src.split('\n'); let i = 0, para = [];
      const flush = () => { if (para.length) { inl(el('span', root, 'md__p'), para.join('\n')); para = []; } };
      while (i < ls.length) {
        const l = ls[i];
        if (/^```/.test(l)) { flush(); const buf = []; i++; while (i < ls.length && !/^```\s*$/.test(ls[i])) buf.push(ls[i++]); i++; el('code', el('pre', root, 'md__pre')).textContent = buf.join('\n'); continue; }
        if (/^>\s?/.test(l)) { flush(); const buf = []; while (i < ls.length && /^>\s?/.test(ls[i])) buf.push(ls[i++].replace(/^>\s?/, '')); inl(el('blockquote', root, 'md__q'), buf.join('\n')); continue; }
        if (/^\s*[-•]\s+/.test(l)) { flush(); const u = el('ul', root, 'md__l'); while (i < ls.length && /^\s*[-•]\s+/.test(ls[i])) inl(el('li', u), ls[i++].replace(/^\s*[-•]\s+/, '')); continue; }
        if (/^\s*\d+[.)]\s+/.test(l)) { flush(); const u = el('ol', root, 'md__l'); while (i < ls.length && /^\s*\d+[.)]\s+/.test(ls[i])) inl(el('li', u), ls[i++].replace(/^\s*\d+[.)]\s+/, '')); continue; }
        if (!l.trim()) { flush(); i++; continue; }
        para.push(l); i++;
      }
      flush();
    });
  }

  fmt(b) { return b < 1024 ? b + ' Б' : b < 1048576 ? Math.round(b / 1024) + ' КБ' : (b / 1048576).toFixed(1).replace('.', ',') + ' МБ'; }
  addFiles(list) {
    const arr = Array.from(list || []); if (!arr.length) return;
    const pend = this.state.pend.slice(); let err = '';
    arr.forEach((f) => {
      if (f.size > 20 * 1048576) { err = 'Файл «' + f.name + '» больше 20 МБ. Выберите файл поменьше.'; return; }
      if (pend.length >= 10) { err = 'Можно прикрепить не больше 10 файлов за раз.'; return; }
      const img = /^image\//.test(f.type);
      pend.push({ id: Math.random().toString(36).slice(2), name: f.name || 'Изображение', size: f.size, img: img, url: img ? URL.createObjectURL(f) : '' });
      if (pend[pend.length - 1].url) { (window.__hbBlobs = window.__hbBlobs || new Set()).add(pend[pend.length - 1].url); }
    });
    this.setState({ pend: pend, ferr: err });
  }
  attRender() {
    const ICON = '<svg class="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>';
    document.querySelectorAll('.bub .att').forEach((root) => {
      const src = root.getAttribute('data-att') || '[]';
      if (root.__src === src && root.firstChild) return;
      root.__src = src; root.textContent = '';
      let a = []; try { a = JSON.parse(src); } catch (e) { a = []; }
      a.forEach((f) => {
        if (f.img && f.url && window.__hbBlobs && window.__hbBlobs.has(f.url)) {
          const b = document.createElement('button'); b.type = 'button'; b.className = 'att__img'; b.setAttribute('aria-label', 'Открыть изображение ' + f.name);
          const im = document.createElement('img'); im.src = f.url; im.alt = f.name;
          im.onload = () => { const t = document.querySelector('.thread'); if (t) t.scrollTop = t.scrollHeight; };
          b.appendChild(im); b.onclick = () => this.setState({ zoom: { url: f.url, name: f.name } }); root.appendChild(b);
        } else {
          const c = document.createElement('div'); c.className = 'att__f';
          const i = document.createElement('span'); i.className = 'att__ic'; i.innerHTML = ICON;
          const n = document.createElement('span'); n.className = 'att__n'; n.textContent = f.name;
          const s = document.createElement('span'); s.className = 'att__s'; s.textContent = f.sizeT || '';
          c.appendChild(i); c.appendChild(n); c.appendChild(s); root.appendChild(c);
        }
      });
    });
  }
  toEnd() {
    this.mdRender(); this.attRender();
    const ta = document.getElementById("m-t");
    if (ta) { ta.style.height = "auto"; ta.style.height = Math.min(ta.scrollHeight + 2, 162) + "px"; }
    const t = document.querySelector(".thread"), k = this.state.cur + ":" + this.state.view + ":" + this.state.thr[this.state.cur].length;
    if (!t || this._end === k) return;
    this._end = k;
    t.scrollTop = t.scrollHeight;
  }
  syncMsg() {
    const S = this.state, un = HB.isNovice() ? { support: 0 } : { support: 1, kamila: 2, georgiy: 0, aliya: 0 };
    const n = Object.keys(un).reduce((a, k) => a + (S.read[k] ? 0 : un[k]), 0);
    if (window.__hbMsgN === n) return;
    window.__hbMsgN = n;
    window.dispatchEvent(new CustomEvent('hb:msgunread', { detail: n }));
  }
  componentWillUnmount() { ['dragenter', 'dragover', 'drop'].forEach((n) => document.removeEventListener(n, this._dnd)); clearTimeout(this._dt); clearTimeout(this._tm); clearTimeout(this._rd); }
  say(t) { this.setState({ toast: t }); clearTimeout(this._tm); this._tm = setTimeout(() => this.setState({ toast: '' }), 4200); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o);
    const D = (HB.isNovice() ? (x) => x.filter((d) => d.id === 'support') : (x) => x)([
      { id: 'support', name: 'Поддержка', av: 'П', role: 'AI-ассистент, затем специалист', tagT: 'Поддержка', unread: HB.isNovice() ? 0 : 1, quick: true },
      { id: 'kamila', name: 'Камила Рашидова', av: 'КР', role: 'Менеджер, клиент Дмитрий Орлов', tagT: 'Менеджер', unread: 2, tag: true },
      { id: 'georgiy', name: 'Георгий Топалов', av: 'ГТ', role: 'Менеджер, клиент Сергей Лукин', tagT: 'Менеджер', unread: 0, tag: true },
      { id: 'aliya', name: 'Алия Нурланова', av: 'АН', role: 'Моя сеть, приглашена Вами', tagT: 'Моя сеть', unread: 0, tag: true }
    ]).concat(Object.keys(S.thr).filter((k) => k.indexOf("net-") === 0).map((k) => { const nm = HB.net.nameOf(k.slice(4)); return { id: k, name: nm, av: nm.split(" ").map((w) => w.charAt(0)).join("").slice(0, 2), role: "Моя сеть, приглашён Вами", unread: 0 }; }));
    const last = (id) => { const a = S.thr[id]; return a[a.length - 1] || { t: '', time: '' }; };
    const un = (d) => S.read[d.id] ? 0 : d.unread;
    const total = D.reduce((n, d) => n + un(d), 0);
    const q = S.q.trim().toLowerCase();
    const shown = D.filter((d) => !q || (d.name + ' ' + d.role + ' ' + S.thr[d.id].map((m) => m.t).join(' ')).toLowerCase().indexOf(q) >= 0);
    const cur = D.filter((d) => d.id === S.cur)[0];
    const now = () => { const d = new Date(); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); };
    const IC = { support: true };
    const dlgs = shown.map((d) => {
      const l = last(d.id), u = un(d);
      return { isSup: d.id === 'support', notSup: d.id !== 'support', name: d.name, av: d.av, time: l.day === 'Сегодня' ? l.time : l.day, tagT: d.tagT, prev: (l.me ? 'Вы: ' : '') + (l.files && l.files.length ? 'Файл: ' + l.files.map((q) => q.name).join(', ') + (l.t ? '. ' : '') : '') + (l.t || '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/```/g, '').replace(/[*_~`]/g, '').replace(/^\s*>\s?/gm, '').replace(/\s*\n\s*/g, ' '), unread: u > 0, unreadN: u, unreadAria: 'Непрочитанных: ' + u,
        cls: u > 0 ? 'is-new' : '', cur: d.id === S.cur ? 'true' : 'false', open: () => set({ cur: d.id, view: 'chat', read: Object.assign({}, S.read, { [d.id]: true }), err: false }) };
    });
    const T = S.thr[S.cur];
    const msgs = T.map((m, i) => { const p = T[i - 1], n = T[i + 1], first = !p || p.day !== m.day || p.me !== m.me, lastS = !n || n.day !== m.day || n.me !== m.me;
      return { sep: !p || p.day !== m.day, day: m.day, me: m.me, cls: (m.me ? 'bub--me ' : '') + (first ? '' : 'bub--c ') + (lastS ? 'bub--last' : ''), t: m.t, hasT: !!m.t, hasF: !!(m.files && m.files.length), att: JSON.stringify(m.files || []), time: m.time, tk: m.st === 'read' ? 'is-read' : '', tkAria: m.st === 'read' ? 'Прочитано' : 'Доставлено' }; });
    const QS = ['Как передать клиента?', 'Как рассчитывается моя доля комиссии?', 'Как пригласить партнёра?'];
    const quick = QS.map((t) => ({ t: t, go: () => set({ thr: Object.assign({}, S.thr, { support: S.thr.support.concat([{ me: true, t: t, time: now(), day: 'Сегодня', st: 'read' }, { me: false, day: 'Сегодня', t: 'В кабинете здесь ответит AI-ассистент. В примере ответ не показан. Если нужен человек, напишите «специалист».', time: now() }]) }) }) }));
    const send = () => {
      const t = S.draft.trim();
      if (!t && !S.pend.length) return;
      const files = S.pend.map((q) => ({ name: q.name, size: q.size, sizeT: this.fmt(q.size), img: q.img, url: q.url }));
      const msg = { me: true, t: t, files: files.length ? files : undefined, time: now(), day: 'Сегодня', st: 'deliv' }, id = S.cur;
      set({ thr: Object.assign({}, S.thr, { [id]: S.thr[id].concat([msg]) }), draft: '', pend: [], ferr: '', err: false });
      clearTimeout(this._rd);
      this._rd = setTimeout(() => this.setState((P) => ({ thr: Object.assign({}, P.thr, { [id]: P.thr[id].map((m) => m.st === 'deliv' ? Object.assign({}, m, { st: 'read' }) : m) }) })), 1800);
    };
    const onKey = (e) => { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); send(); } };
    return {
      leadT: total > 0 ? 'Непрочитанных: ' + total + '.' : 'Всё прочитано.', helpOpen: S.helpOpen, toggleHelp: () => set({ helpOpen: !S.helpOpen }),
      view: S.view, q: S.q, onQ: (e) => set({ q: e.target.value }), dlgs: dlgs, noDlg: shown.length === 0,
      wa: () => this.say('В кабинете откроется WhatsApp со службой поддержки'),
      cur: { isSup: cur.id === 'support', notSup: cur.id !== 'support', av: cur.av, name: cur.name, role: cur.role, logAria: 'Переписка: ' + cur.name, quick: !!cur.quick }, msgs: msgs, quick: quick,
      toList: () => set({ view: 'list' }),
      draft: S.draft, onDraft: (e) => set({ draft: e.target.value, err: false }), send: send, onKey: onKey, noSend: !S.draft.trim() && !S.pend.length,
      hasPend: S.pend.length > 0, ferr: S.ferr,
      pend: S.pend.map((q) => ({ name: q.name, sizeT: this.fmt(q.size), img: q.img, notImg: !q.img, url: q.url, dropAria: 'Убрать файл ' + q.name, drop: () => { if (q.url) URL.revokeObjectURL(q.url); set({ pend: S.pend.filter((z) => z.id !== q.id), ferr: '' }); } })),
      toggleFile: () => { const i = document.getElementById('m-f'); if (i) i.click(); },
      onFiles: (e) => { this.addFiles(e.target.files); e.target.value = ''; },
      onPaste: (e) => { const fs = Array.from((e.clipboardData && e.clipboardData.files) || []).filter((q) => /^image\//.test(q.type)); if (fs.length) { e.preventDefault(); this.addFiles(fs); } },
      zoomOn: !!S.zoom, zoomUrl: S.zoom ? S.zoom.url : '', zoomName: S.zoom ? S.zoom.name : '', closeZoom: () => set({ zoom: null }),
      toastOn: !!S.toast, toast: S.toast, closeToast: () => set({ toast: '' })
    };
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); if (HB.isNovice() && this.state.cur !== 'support') this.state.cur = 'support'; const nc = HB.store.get('msg.cur'); if (nc) { this.state.cur = nc; this.state.view = 'chat'; HB.store.remove('msg.cur'); } }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o);  return v; }
}; })(Component);

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props);  }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); v.hasMgr = !HB.isNovice(); if (HB.isNovice()) v.leadT = 'Чаты с менеджерами по клиентам появятся после первой передачи клиента. Пока можно написать в поддержку.'; return v; }
}; })(Component);
